// Part: room: owner stair hall (interior). The flight x86 z14->10 is built and locked; this furnishes only the air
// cells round it (the box is one column wide, so the hall is the stair well). A coat rack at the north end where the
// hall meets the parlor opening, lanterns hung from the stair's stringer and the upper floor so the climb is lit.
import { B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

export function build(g) {
  // Coat rack: a spruce fence post on the floor, a black banner standing on its top (the coat on the hook)
  g.set(86, 2, 10, "minecraft:spruce_fence");
  g.set(86, 3, 10, ...B.banner("black", [], { wall: false, rotation: 0 }));

  // Lanterns hanging: under the stair's top stringer at the north end, and under the upper floor over the landing
  g.set(86, 4, 10, ...B.lantern(true));
  g.set(86, 5, 14, ...B.lantern(true));
}

